import React from "react";
import { Routes, Route, Link, useNavigate } from "react-router-dom";
import Signup from "./Signup";
import Login from "./Login";
import Courses from "./Courses";
import TeacherDashboard from "./TeacherDashboard";
import StudentDashboard from "./StudentDashboard";
import Planner from "./Planner";

function Navbar() {
  const navigate = useNavigate();

  const userName = localStorage.getItem("user_name");
  const role = localStorage.getItem("role");

  const handleLogout = () => {
    localStorage.clear();
    navigate("/");
  };

  return (
    <nav
      style={{
        display: "flex",
        justifyContent: "space-between",
        alignItems: "center",
        padding: "18px 40px",
        background: "#ffffff",
        boxShadow: "0 4px 12px rgba(0,0,0,0.08)",
      }}
    >
      <h2 style={{ color: "#4b1b85" }}>LMS Platform</h2>

      <div style={{ display: "flex", gap: "20px", alignItems: "center" }}>
        {!userName && (
          <>

            <Link to="">LEARN WITH SMART</Link>
          </>
        )}

        {userName && (
          <>
            <Link to="/courses">Courses</Link>

            {role === "teacher" && <Link to="/teacher-dashboard">Teacher Panel</Link>}
            {role === "student" && <Link to="/student-dashboard">Student Panel</Link>}
            {role === "planner" &7}

            <span style={{ color: "#7b1fa2", fontWeight: "bold" }}>
              Hi, {userName}
            </span>

            <button
              onClick={handleLogout}
              style={{
                background: "#7b1fa2",
                color: "#fff",
                border: "none",
                padding: "8px 14px",
                borderRadius: "8px",
                cursor: "pointer"
              }}
            >
              Logout
            </button>
          </>
        )}
      </div>
    </nav>
  );
}

function App() {
  return (
    <div style={{ minHeight: "100vh", background: "linear-gradient(135deg, #e0f7fa, #f3e5f5)" }}>
      <Navbar />
      <div style={{ maxWidth: "1100px", margin: "30px auto", padding: "20px" }}>
        <div style={{ background: "#fff", borderRadius: "18px", boxShadow: "0 8px 25px rgba(0,0,0,0.1)", padding: "30px" }}>
          <Routes>
            <Route path="/" element={<Login />} />
            <Route path="/signup" element={<Signup />} />
            <Route path="/courses" element={<Courses />} />
            <Route path="/teacher-dashboard" element={<TeacherDashboard />} />
            <Route path="/student-dashboard" element={<StudentDashboard />} />
            <Route path="./planner" element= {<Planner/>} />
          </Routes>
        </div>
      </div>
    </div>
  );
}

export default App;
